}

.thumb {
  flex-shrink: 0;
  width: 46px;
  height: 69px;
  border-radius: 6px;
  object-fit: cover;
}

.thumb-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--surface-muted);
}

// Text column grows, but the link inside only covers the title text
.item-text {
  display: flex;
  flex: 1;
  flex-direction: column;
  align-items: flex-start;
  min-width: 0;
}

.title-link {
  color: var(--text);
  font-weight: 700;
